import { createHmac, timingSafeEqual } from 'node:crypto';

export interface Session {
  userId: string;
  issuedAt: number;
  expiresAt: number;
}

const SECRET = process.env.AUTH_SECRET ?? 'dev-secret-do-not-use-in-prod';
/** Tolerated clock drift between the issuing and verifying hosts. */
const CLOCK_SKEW_MS = 60_000;

function sign(payload: string): string {
  return createHmac('sha256', SECRET).update(payload).digest('base64url');
}

export function signSession(session: Session): string {
  const payload = Buffer.from(JSON.stringify(session)).toString('base64url');
  return `${payload}.${sign(payload)}`;
}

export function verifySession(token: string, now: number = Date.now()): Session | null {
  const [payload, signature] = token.split('.');
  if (!payload || !signature) return null;
  const expected = sign(payload);
  if (signature.length !== expected.length) return null;
  if (!timingSafeEqual(Buffer.from(signature), Buffer.from(expected))) return null;
  const session = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as Session;
  if (session.expiresAt <= now + CLOCK_SKEW_MS) return null;
  return session;
}

import { describe, expect, it } from 'vitest';
import { signSession, verifySession } from '../src/auth.js';

const now = 1_700_000_000_000;

describe('verifySession', () => {
  it('accepts a freshly signed session', () => {
    const session = { userId: 'u42', issuedAt: now, expiresAt: now + 60_000 };
    expect(verifySession(signSession(session), now)).toEqual(session);
  });

  it('rejects an expired session', () => {
    const session = { userId: 'u42', issuedAt: now - 120_000, expiresAt: now - 60_000 };
    expect(verifySession(signSession(session), now)).toBeNull();
  });

  it('rejects a tampered signature', () => {
    const token = signSession({ userId: 'u42', issuedAt: now, expiresAt: now + 60_000 });
    expect(verifySession(`${token.slice(0, -1)}x`, now)).toBeNull();
  });
});

